  font-size: .875rem;
  font-weight: 600;
  color: var(--clr-accent);
  white-space: nowrap;
  transition: opacity .2s;
}
.view-all:hover { opacity: .7; }

/* ─── Navbar ───────────────────────────────────────────────── */
#navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-h);
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
  transition: box-shadow .2s;
}
#navbar.scrolled { box-shadow: 0 2px 16px rgba(0,0,0,.08); }

.nav-inner {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 40px;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.03em;
  flex-shrink: 0;
}
.nav-logo span { color: var(--clr-accent); }

.nav-links {
  display: flex;
  gap: 28px;
  font-size: .875rem;
  font-weight: 500;
}
.nav-links a { color: var(--clr-ink-muted); transition: color .2s; }
.nav-links a:hover { color: var(--clr-ink); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.nav-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: 50%;
  transition: background .2s;
  position: relative;
}
.nav-btn:hover { background: var(--clr-bg); }
.nav-btn svg { width: 20px; height: 20px; stroke: var(--clr-ink); fill: none; stroke-width: 1.8; }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--clr-accent);
  color: #fff;
  border-radius: 50%;
  font-size: .6rem;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}

.nav-cta {
  margin-left: 8px;
  padding: 8px 20px;
  background: var(--clr-ink);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  transition: background .2s, transform .15s;
}
.nav-cta:hover { background: #333; transform: translateY(-1px); }

/* ─── Announcement Bar ─────────────────────────────────────── */
.announcement-bar {
  background: var(--clr-ink);
  color: #fff;
  text-align: center;
  font-size: .8125rem;
  font-weight: 500;
  padding: 10px 24px;
  letter-spacing: .02em;
}
.announcement-bar span { color: var(--clr-accent); font-weight: 700; }

/* ─── Hero ─────────────────────────────────────────────────── */
#hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: calc(90vh - var(--nav-h));
  overflow: hidden;
}

.hero-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 80px 64px 80px 0;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 20px;
}
.hero-eyebrow::before {
  content: '';
  width: 28px; height: 2px;
  background: var(--clr-accent);
  border-radius: 2px;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 24px;
}
.hero-title em {
  font-style: italic;
  color: var(--clr-accent);
}

.hero-body {
  font-size: 1.0625rem;
  color: var(--clr-ink-muted);
  max-width: 440px;
  margin-bottom: 40px;
  line-height: 1.7;
}

.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 32px;
  background: var(--clr-ink);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 600;
  transition: background .2s, transform .15s;
}
.btn-primary:hover { background: #333; transform: translateY(-2px); }
.btn-primary svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2; }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border: 1.5px solid var(--clr-border);
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 600;
  color: var(--clr-ink);
  transition: border-color .2s, background .2s;
}
.btn-ghost:hover { border-color: var(--clr-ink); background: var(--clr-bg); }

.hero-stats {
  display: flex;
  gap: 40px;
  margin-top: 52px;
  padding-top: 40px;
  border-top: 1px solid var(--clr-border);
}
.stat-num {
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -.03em;
}
.stat-label {
  font-size: .8125rem;
  color: var(--clr-ink-muted);
  margin-top: 2px;
}

.hero-visual {
  position: relative;
  background: #f0ece6;
  overflow: hidden;
}

.hero-image-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  grid-template-rows: 1fr 1fr;
  height: 100%;
  gap: 4px;
}

.hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-img-main {
  grid-row: 1 / 3;
  height: 100%;
}

.hero-tag {
  position: absolute;
  bottom: 32px;
  left: 32px;
  background: #fff;
  padding: 14px 20px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  gap: 12px;
}
.hero-tag-icon { font-size: 1.5rem; }
.hero-tag-text { font-size: .8125rem; font-weight: 700; }
.hero-tag-sub { font-size: .75rem; color: var(--clr-ink-muted); margin-top: 1px; }

/* ─── Brands Strip ─────────────────────────────────────────── */
.brands-strip {
  border-top: 1px solid var(--clr-border);
  border-bottom: 1px solid var(--clr-border);
  background: var(--clr-surface);
  padding: 28px 0;
}

.brands-inner {
  display: flex;
  align-items: center;
  gap: 48px;
  overflow-x: auto;
  scrollbar-width: none;
}
.brands-inner::-webkit-scrollbar { display: none; }

.brand-label {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-ink-muted);
  white-space: nowrap;
  flex-shrink: 0;
  padding-right: 48px;
  border-right: 1px solid var(--clr-border);
}

.brand-logo {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  font-weight: 700;
  color: #b0a99e;
  white-space: nowrap;
  flex-shrink: 0;
  letter-spacing: .04em;
  transition: color .2s;
}
.brand-logo:hover { color: var(--clr-ink); }

/* ─── Sections shared ──────────────────────────────────────── */
.section { padding: 80px 0; }
.section--alt { background: var(--clr-surface); }

/* ─── Category Pills ───────────────────────────────────────── */
.category-pills {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 36px;
}

.pill {
  padding: 8px 20px;
  border-radius: 100px;
  font-size: .8125rem;
  font-weight: 600;
  border: 1.5px solid var(--clr-border);
  color: var(--clr-ink-muted);
  transition: all .2s;
}
.pill:hover, .pill.active {
  border-color: var(--clr-ink);
  background: var(--clr-ink);
  color: #fff;
}

/* ─── Product Grid ─────────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform .25s, box-shadow .25s;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }

.product-card__media {
  position: relative;
  aspect-ratio: 3/4;
  background: #f3f0ec;
  overflow: hidden;
}

.product-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-card__img { transform: scale(1.04); }

.product-card__badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge--new    { background: var(--clr-ink); color: #fff; }
.badge--sale   { background: var(--clr-accent); color: #fff; }
.badge--hot    { background: #e8b435; color: #fff; }

.product-card__wishlist {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 34px; height: 34px;
  background: rgba(255,255,255,.9);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(4px);
  transition: background .2s, transform .2s;
}
.product-card__wishlist:hover { background: #fff; transform: scale(1.1); }
.product-card__wishlist svg { width: 16px; height: 16px; stroke: var(--clr-ink); fill: none; stroke-width: 2; }
.product-card__wishlist.active svg { fill: #e53e3e; stroke: #e53e3e; }

.product-card__quick-add {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 12px;
  background: linear-gradient(to top, rgba(0,0,0,.7) 0%, transparent 100%);
  transform: translateY(100%);
  transition: transform .25s;
  display: flex;
  gap: 8px;
}
.product-card:hover .product-card__quick-add { transform: translateY(0); }

.quick-add-btn {
  flex: 1;
  padding: 10px;
  background: #fff;
  color: var(--clr-ink);
  border-radius: var(--radius-sm);
  font-size: .8125rem;
  font-weight: 700;
  text-align: center;
  transition: background .15s;
}
.quick-add-btn:hover { background: var(--clr-accent); color: #fff; }

.product-card__body {
  padding: 16px 16px 20px;
}

.product-card__brand {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-ink-muted);
  margin-bottom: 4px;
}

.product-card__name {
  font-size: .9375rem;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 8px;
}

.product-card__stars {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 10px;
}
.stars { display: flex; gap: 2px; }
.stars svg { width: 12px; height: 12px; }
.star-fill { fill: #f5c842; stroke: none; }
.star-empty { fill: #e0dbd4; stroke: none; }
.review-count { font-size: .75rem; color: var(--clr-ink-muted); }

.product-card__price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.price-current { font-size: 1.0625rem; font-weight: 700; }
.price-original { font-size: .875rem; color: var(--clr-ink-muted); text-decoration: line-through; }
.price-save { font-size: .75rem; font-weight: 700; color: var(--clr-accent); }

/* ─── Deals Section ────────────────────────────────────────── */
.deals-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  grid-template-rows: repeat(2, auto);
  gap: 20px;
}

.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 28px;
  background: #e8e2db;
  transition: transform .25s, box-shadow .25s;
}
.deal-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }

.deal-card--featured {
  grid-row: 1 / 3;
  min-height: 540px;
}

.deal-card__bg {
  position: absolute;
  inset: 0;
  object-fit: cover;
  width: 100%;
  height: 100%;
  transition: transform .4s;
}
.deal-card:hover .deal-card__bg { transform: scale(1.04); }

.deal-card__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10,8,5,.75) 0%, rgba(10,8,5,.1) 55%, transparent 100%);
}

.deal-card__content { position: relative; z-index: 1; color: #fff; }

.deal-card__label {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  background: var(--clr-accent);
  color: #fff;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  display: inline-block;
  margin-bottom: 12px;
}

.deal-card__title {
  font-family: var(--font-serif);
  font-size: clamp(1.2rem, 2.2vw, 1.75rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 8px;
}

.deal-card__sub {
  font-size: .875rem;
  opacity: .8;
  margin-bottom: 20px;
  line-height: 1.5;
}

.deal-timer {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
.timer-block {
  background: rgba(255,255,255,.15);
  backdrop-filter: blur(6px);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  text-align: center;
  min-width: 52px;
}
.timer-num { font-size: 1.25rem; font-weight: 700; line-height: 1; }
.timer-unit { font-size: .65rem; text-transform: uppercase; letter-spacing: .06em; opacity: .7; margin-top: 2px; }

.deal-card__btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 11px 22px;
  background: #fff;
  color: var(--clr-ink);
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 700;
  transition: background .15s, color .15s;
}
.deal-card__btn:hover { background: var(--clr-accent); color: #fff; }
.deal-card__btn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.2; }

/* ─── Editorial Grid ───────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 32px;
}

.editorial-featured {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #f3f0ec;
  display: grid;
  grid-template-rows: 1fr auto;
}

.editorial-featured__media {
  aspect-ratio: 16/9;
  overflow: hidden;
}
.editorial-featured__media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s;
}
.editorial-featured:hover .editorial-featured__media img { transform: scale(1.04); }

.editorial-featured__body {
  padding: 32px;
}

.editorial-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 12px;
}

.editorial-featured__title {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -.02em;
  margin-bottom: 12px;
}

.editorial-featured__excerpt {
  font-size: .9375rem;
  color: var(--clr-ink-muted);
  line-height: 1.7;
  margin-bottom: 24px;
}

.editorial-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.editorial-card {
  display: flex;
  gap: 16px;
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform .2s, box-shadow .2s;
}
.editorial-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-hover); }

.editorial-card__media {
  width: 110px;
  flex-shrink: 0;
  overflow: hidden;
}
.editorial-card__media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s;
}
.editorial-card:hover .editorial-card__media img { transform: scale(1.06); }

.editorial-card__body {
  padding: 16px 16px 16px 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.editorial-card__tag {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 6px;
}

.editorial-card__title {
  font-size: .9375rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 6px;
}

.editorial-card__meta {
  font-size: .75rem;
  color: var(--clr-ink-muted);
}

/* ─── Newsletter ───────────────────────────────────────────── */
#newsletter {
  background: var(--clr-ink);
  color: #fff;
  padding: 80px 0;
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.newsletter-title {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -.03em;
  line-height: 1.15;
  margin-bottom: 12px;
}
.newsletter-title em { font-style: italic; color: #d4a97a; }

.newsletter-sub {
  font-size: .9375rem;
  color: rgba(255,255,255,.6);
  line-height: 1.7;
}

.newsletter-perks {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 28px;
}
.perk {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: .875rem;
  color: rgba(255,255,255,.75);
}
.perk-dot {
  width: 8px; height: 8px;
  background: #d4a97a;
  border-radius: 50%;
  flex-shrink: 0;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-row { display: flex; gap: 12px; }

.input {
  flex: 1;
  padding: 14px 18px;
  background: rgba(255,255,255,.08);
  border: 1.5px solid rgba(255,255,255,.15);
  border-radius: var(--radius-sm);
  color: #fff;
  font-size: .9375rem;
  font-family: var(--font-sans);
  transition: border-color .2s, background .2s;
}
.input::placeholder { color: rgba(255,255,255,.4); }
.input:focus { outline: none; border-color: rgba(255,255,255,.4); background: rgba(255,255,255,.12); }

.submit-btn {
  padding: 14px 28px;
  background: #d4a97a;
  color: var(--clr-ink);
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 700;
  transition: background .2s, transform .15s;
  white-space: nowrap;
}
.submit-btn:hover { background: #c49360; transform: translateY(-1px); }

.form-note {
  font-size: .75rem;
  color: rgba(255,255,255,.4);
}

/* ─── Footer ───────────────────────────────────────────────── */
footer {
  background: #111;
  color: rgba(255,255,255,.6);
  padding: 64px 0 32px;
}

.footer-top {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 56px;
}

.footer-brand { }
.footer-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: -.03em;
  margin-bottom: 16px;
}
.footer-logo span { color: #d4a97a; }

.footer-desc {
  font-size: .875rem;
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: 280px;
}

.social-links { display: flex; gap: 12px; }
.social-btn {
  width: 38px; height: 38px;
  background: rgba(255,255,255,.08);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  transition: background .2s;
  font-size: .75rem;
  font-weight: 700;
  color: rgba(255,255,255,.7);
}
.social-btn:hover { background: rgba(255,255,255,.18); color: #fff; }

.footer-col-title {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 20px;
}

.footer-links { display: flex; flex-direction: column; gap: 12px; }
.footer-links a {
  font-size: .875rem;
  transition: color .2s;
}
.footer-links a:hover { color: #fff; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.08);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: .8125rem;
  flex-wrap: wrap;
  gap: 12px;
}

.payment-methods {
  display: flex;
  gap: 8px;
  align-items: center;
}
.pay-badge {
  background: rgba(255,255,255,.1);
  border-radius: 4px;
  padding: 4px 10px;
  font-size: .7rem;
  font-weight: 700;
  color: rgba(255,255,255,.6);
  letter-spacing: .04em;
}

/* ─── Mini Cart Drawer ─────────────────────────────────────── */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.4);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s;
}
.cart-overlay.open { opacity: 1; pointer-events: all; }

