  const stars = [
    ...Array(full).fill('<svg class="star-fill" viewBox="0 0 12 12"><path d="M6 1l1.39 2.82L10.5 4.3l-2.25 2.2.53 3.11L6 8.01 3.22 9.61l.53-3.11L1.5 4.3l3.11-.48L6 1z"/></svg>'),
    ...Array(empty).fill('<svg class="star-empty" viewBox="0 0 12 12"><path d="M6 1l1.39 2.82L10.5 4.3l-2.25 2.2.53 3.11L6 8.01 3.22 9.61l.53-3.11L1.5 4.3l3.11-.48L6 1z"/></svg>'),
  ].join('');
  return `
    <div class="product-card__stars">
      <div class="stars">${stars}</div>
      <span class="review-count">${rating} (${reviews.toLocaleString()})</span>
    </div>`;
}

/* ── ProductCard ───────────────────────────────────────────── */
function ProductCard(product) {
  const { id, brand, name, price, originalPrice, rating, reviews, badge, color, emoji } = product;
  const discount = originalPrice ? Math.round((1 - price / originalPrice) * 100) : null;

  const badgeHTML = badge ? `<div class="product-card__badges"><span class="badge badge--${badge}">${badge === 'new' ? 'New' : badge === 'sale' ? 'Sale' : '🔥 Hot'}</span></div>` : '';

  return `
    <article class="product-card" data-id="${id}">
      <div class="product-card__media" style="background:${color}">
        <div class="product-card__emoji-placeholder" style="display:flex;align-items:center;justify-content:center;height:100%;font-size:5rem;">${emoji}</div>
        ${badgeHTML}
        <button class="product-card__wishlist${wishlist.has(id) ? ' active' : ''}" data-wishlist="${id}" aria-label="Add to wishlist">
          <svg viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
        </button>
        <div class="product-card__quick-add">
          <button class="quick-add-btn" data-addcart="${id}">+ Add to Cart</button>
        </div>
      </div>
      <div class="product-card__body">
        <div class="product-card__brand">${brand}</div>
        <div class="product-card__name">${name}</div>
        ${StarRating({ rating, reviews })}
        <div class="product-card__price">
          <span class="price-current">$${price}</span>
          ${originalPrice ? `<span class="price-original">$${originalPrice}</span><span class="price-save">−${discount}%</span>` : ''}
        </div>
      </div>
    </article>`;
}

/* ── DealCard ──────────────────────────────────────────────── */
function DealCard(deal) {
  const timerHTML = deal.timer ? `
    <div class="deal-timer" id="deal-timer">
      <div class="timer-block"><div class="timer-num" id="t-h">18</div><div class="timer-unit">hrs</div></div>
      <div class="timer-block"><div class="timer-num" id="t-m">00</div><div class="timer-unit">min</div></div>
      <div class="timer-block"><div class="timer-num" id="t-s">00</div><div class="timer-unit">sec</div></div>
    </div>` : '';

  return `
    <a href="#" class="deal-card${deal.featured ? ' deal-card--featured' : ''}" style="background:${deal.bg}">
      <div class="deal-card__overlay"></div>
      <div class="deal-card__content">
        <span class="deal-card__label">${deal.label}</span>
        <h3 class="deal-card__title">${deal.title.replace('\n','<br>')}</h3>
        <p class="deal-card__sub">${deal.sub}</p>
        ${timerHTML}
        <span class="deal-card__btn">
          Shop Now
          <svg viewBox="0 0 24 24"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
        </span>
      </div>
    </a>`;
}

/* ── EditorialFeatured ─────────────────────────────────────── */
function EditorialFeatured(article) {
  return `
    <a href="#" class="editorial-featured">
      <div class="editorial-featured__media">
        <div style="background:${article.bg};display:flex;align-items:center;justify-content:center;height:100%;font-size:7rem;">${article.emoji}</div>
      </div>
      <div class="editorial-featured__body">
        <div class="editorial-tag">✦ ${article.tag}</div>
        <h3 class="editorial-featured__title">${article.title}</h3>
        <p class="editorial-featured__excerpt">${article.excerpt}</p>
        <div style="display:flex;gap:16px;align-items:center;">
          <span style="font-size:.875rem;font-weight:600;">${article.author}</span>
          <span style="font-size:.8125rem;color:var(--clr-ink-muted);">${article.date} · ${article.readTime}</span>
        </div>
      </div>
    </a>`;
}

/* ── EditorialCard ─────────────────────────────────────────── */
function EditorialCard(article) {
  return `
    <a href="#" class="editorial-card">
      <div class="editorial-card__media" style="background:${article.bg};display:flex;align-items:center;justify-content:center;font-size:3rem;">
        ${article.emoji}
      </div>
      <div class="editorial-card__body">
        <div class="editorial-card__tag">${article.tag}</div>
        <div class="editorial-card__title">${article.title}</div>
        <div class="editorial-card__meta">${article.date} · ${article.readTime}</div>
      </div>
    </a>`;
}

/* ── CartItem ──────────────────────────────────────────────── */
function CartItem({ id, qty }) {
  const p = DATA.products.find(x => x.id === id);
  if (!p) return '';
  return `
    <div class="cart-item" data-cart-id="${id}">
      <div class="cart-item-img" style="display:flex;align-items:center;justify-content:center;font-size:2.5rem;background:${p.color};">${p.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-brand">${p.brand}</div>
        <div class="cart-item-name">${p.name}</div>
        <div class="cart-item-qty">
          <button class="qty-btn" data-qty="${id}" data-delta="-1">−</button>
          <span>${qty}</span>
          <button class="qty-btn" data-qty="${id}" data-delta="1">+</button>
        </div>
      </div>
      <div class="cart-item-price">$${(p.price * qty).toLocaleString()}</div>
    </div>`;
}

/* ── Render cart drawer ────────────────────────────────────── */
function cartRender() {
  const body = document.querySelector('.cart-body');
  const subtotal = document.querySelector('.cart-subtotal strong');
  if (!body) return;
  body.innerHTML = cart.items.length
    ? cart.items.map(CartItem).join('')
    : '<p style="color:var(--clr-ink-muted);font-size:.9rem;padding:24px 0;">Your cart is empty.</p>';
  if (subtotal) subtotal.textContent = `$${cart.total.toLocaleString()}`;
}

function updateBadge() {
  const badge = document.getElementById('cart-count');
  if (badge) {
    badge.textContent = cart.count;
    badge.style.display = cart.count ? 'flex' : 'none';
  }
}

/* ── Toast ─────────────────────────────────────────────────── */
function showToast(msg, icon = '✅') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = `<span class="toast-icon">${icon}</span> ${msg}`;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), 2600);
}

/* ── Countdown timer ───────────────────────────────────────── */
function tickTimer() {
  const diff = Math.max(0, dealEnd - Date.now());
  const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
  const m = String(Math.floor((diff % 3600000) / 60000)).padStart(2, '0');
  const s = String(Math.floor((diff % 60000) / 1000)).padStart(2, '0');
  const tH = document.getElementById('t-h');
  const tM = document.getElementById('t-m');
  const tS = document.getElementById('t-s');
  if (tH) tH.textContent = h;
  if (tM) tM.textContent = m;
  if (tS) tS.textContent = s;
}

/* ── Active category filter ────────────────────────────────── */
let activeCategory = 'All';

function renderProducts(category) {
  activeCategory = category;
  const filtered = category === 'All'
    ? DATA.products
    : DATA.products.filter(p => p.category === category);

  document.getElementById('product-grid').innerHTML = filtered.map(ProductCard).join('');

  document.querySelectorAll('.pill').forEach(pill => {
    pill.classList.toggle('active', pill.dataset.category === category);
  });
}

/* ════════════════════════════════════════════════════════════
   MOUNT  – build & attach everything once DOM is ready
   ════════════════════════════════════════════════════════════ */
document.addEventListener('DOMContentLoaded', () => {

  /* ── Category pills ── */
  const pillsEl = document.getElementById('category-pills');
  pillsEl.innerHTML = DATA.categories.map(cat =>
    `<button class="pill${cat === 'All' ? ' active' : ''}" data-category="${cat}">${cat}</button>`
  ).join('');

  /* ── Products ── */
  renderProducts('All');

  /* ── Deals ── */
  document.getElementById('deals-grid').innerHTML = DATA.deals.map(DealCard).join('');

  /* ── Editorial ── */
  const featured = DATA.editorial.find(e => e.featured);
  const side     = DATA.editorial.filter(e => !e.featured);
  document.getElementById('editorial-featured').innerHTML = EditorialFeatured(featured);
  document.getElementById('editorial-list').innerHTML     = side.map(EditorialCard).join('');

  /* ── Initial cart ── */
  cartRender();
  updateBadge();

  /* ── Timer ── */
  tickTimer();
  setInterval(tickTimer, 1000);

  /* ── Navbar scroll shadow ── */
  window.addEventListener('scroll', () => {
    document.getElementById('navbar').classList.toggle('scrolled', window.scrollY > 10);
  }, { passive: true });

  /* ── Delegated event handling ── */
  document.addEventListener('click', e => {

    /* Category pills */
    const pill = e.target.closest('.pill');
    if (pill) { renderProducts(pill.dataset.category); return; }

    /* Add to cart */
    const addBtn = e.target.closest('[data-addcart]');
    if (addBtn) {
      const id = parseInt(addBtn.dataset.addcart);
      cart.add(id);
      const p = DATA.products.find(x => x.id === id);
      showToast(`${p.emoji} <strong>${p.name}</strong> added to cart`);
      return;
    }

    /* Wishlist toggle */
    const wlBtn = e.target.closest('[data-wishlist]');
    if (wlBtn) {
      const id = parseInt(wlBtn.dataset.wishlist);
      if (wishlist.has(id)) {
        wishlist.delete(id);
        wlBtn.classList.remove('active');
        showToast('Removed from wishlist', '🤍');
      } else {
        wishlist.add(id);
        wlBtn.classList.add('active');
        showToast('Saved to wishlist', '❤️');
      }
      return;
    }

    /* Qty buttons */
    const qtyBtn = e.target.closest('[data-qty]');
    if (qtyBtn) {
      cart.adjustQty(parseInt(qtyBtn.dataset.qty), parseInt(qtyBtn.dataset.delta));
      return;
    }

    /* Open cart */
    const cartTrigger = e.target.closest('#cart-trigger');
    if (cartTrigger) { openCart(); return; }

    /* Close cart */
    if (e.target.closest('#cart-close') || e.target.closest('#cart-overlay')) { closeCart(); return; }
  });

  /* ── Newsletter form ── */
  document.getElementById('newsletter-form')?.addEventListener('submit', e => {
    e.preventDefault();
    const input = e.target.querySelector('.input');
    if (!input.value) return;
    showToast('🎉 You\'re subscribed! Check your inbox.');
    input.value = '';
  });
});

function openCart() {
  document.getElementById('cart-overlay').classList.add('open');
  document.getElementById('cart-drawer').classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeCart() {
  document.getElementById('cart-overlay').classList.remove('open');
  document.getElementById('cart-drawer').classList.remove('open');
  document.body.style.overflow = '';
}
